// ─── File: BulkUpdateDemo.java ───
// Runnable demo mimicking Spring Data @Modifying behavior:
//  - bulk UPDATE bypasses the persistence context (first-level cache)
//  - flushAutomatically writes pending changes BEFORE the bulk query
//  - clearAutomatically drops the cache AFTER so re-reads are fresh

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class BulkUpdateDemo {
    private static final Logger log = Logger.getLogger("BankInterest");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Database db = new Database();
        PersistenceContext pc = new PersistenceContext(db, log);
        AccountRepository repo = new AccountRepository(db, pc, log);
        InterestService service = new InterestService(repo, pc, log);

        service.applyMonthlyInterest(new BigDecimal("0.01")); // 1% interest
    }
}

// ─── model/Account.java (entity) ───
class Account {
    private final String accountId; private final String holderName;
    private String type; private BigDecimal balance;
    Account(String id, String name, String type, BigDecimal bal) {
        accountId=id; holderName=name; this.type=type; balance=bal;
    }
    String getAccountId() { return accountId; }
    String getType() { return type; }
    BigDecimal getBalance() { return balance; }
    void setBalance(BigDecimal b) { balance = b; }
    Account copy() { return new Account(accountId, holderName, type, balance); }
}

// ─── The actual database (source of truth) ───
class Database {
    final Map<String, Account> rows = new HashMap<>();
    Database() {
        rows.put("SAV2001", new Account("SAV2001", "Rajesh Kumar", "SAVINGS", new BigDecimal("1000000")));
        rows.put("CUR3001", new Account("CUR3001", "Priya Sharma", "CURRENT", new BigDecimal("250000")));
    }
    // Bulk UPDATE runs straight on DB, ignoring any in-memory cache
    int bulkApplyInterest(BigDecimal rate) {
        int updated = 0;
        for (Account a : rows.values()) {
            if ("SAVINGS".equals(a.getType())) {
                a.setBalance(a.getBalance().add(a.getBalance().multiply(rate)));
                updated++;
            }
        }
        return updated;
    }
    Account read(String id) { return rows.get(id); }
}

// ─── The first-level cache / persistence context ───
class PersistenceContext {
    private final Database db; private final Logger log;
    private final Map<String, Account> cache = new HashMap<>();
    PersistenceContext(Database db, Logger log) { this.db = db; this.log = log; }
    // Load returns a cached copy (stale after a bulk update unless cleared)
    Account find(String id) {
        return cache.computeIfAbsent(id, k -> {
            log.fine(() -> "Loading " + k + " from DB into persistence context");
            return db.read(k).copy();
        });
    }
    void flush() { log.fine(() -> "FLUSH: pending changes written to DB"); }
    void clear() { log.fine(() -> "CLEAR: persistence context emptied, next read hits DB"); cache.clear(); }
}

// ─── repository/AccountRepository.java ───
// Real Spring:
//   @Modifying(clearAutomatically = true, flushAutomatically = true)
//   @Query("UPDATE Account a SET a.balance = a.balance + a.balance * :rate WHERE a.type = 'SAVINGS'")
//   int applyInterest(@Param("rate") BigDecimal rate);
class AccountRepository {
    private final Database db; private final PersistenceContext pc; private final Logger log;
    AccountRepository(Database db, PersistenceContext pc, Logger log) {
        this.db=db; this.pc=pc; this.log=log;
    }
    int applyInterest(BigDecimal rate) {
        pc.flush();                              // flushAutomatically = true
        int n = db.bulkApplyInterest(rate);      // bulk UPDATE bypasses cache
        log.info(() -> "Bulk UPDATE applied interest to " + n + " savings accounts");
        pc.clear();                              // clearAutomatically = true
        return n;
    }
    Account findById(String id) { return pc.find(id); }
}

// ─── service/InterestService.java ───
class InterestService {
    private final AccountRepository repo; private final PersistenceContext pc; private final Logger log;
    InterestService(AccountRepository repo, PersistenceContext pc, Logger log) {
        this.repo=repo; this.pc=pc; this.log=log;
    }
    // @Transactional — required for the modifying query
    void applyMonthlyInterest(BigDecimal rate) {
        // Load Rajesh BEFORE the bulk update -> enters persistence context
        Account before = repo.findById("SAV2001");
        log.info(() -> "Rajesh balance BEFORE bulk update (cached) = " + before.getBalance());

        int n = repo.applyInterest(rate);        // flush, bulk UPDATE, clear

        // Read Rajesh AGAIN -> cache was cleared, so fetches FRESH from DB
        Account after = repo.findById("SAV2001");
        log.info(() -> "Rajesh balance AFTER bulk update (fresh) = " + after.getBalance());
        log.info(() -> "Priya (CURRENT, not a savings account) = " + repo.findById("CUR3001").getBalance());
        log.info(() -> "Accounts updated = " + n);
    }
}

// ─── Clean log formatter ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$-7s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel().getName(), r.getMessage());
    }
}
