// ─── File: src/main/java/com/bank/interest/repository/AccountRepository.java ───
package com.bank.interest.repository;

import com.bank.interest.model.Account;
import org.springframework.data.jpa.repository.*;
import org.springframework.data.repository.query.Param;
import java.math.BigDecimal;

public interface AccountRepository extends JpaRepository<Account, String> {

    @Modifying(clearAutomatically = true, flushAutomatically = true)
    @Query("UPDATE Account a SET a.balance = a.balance + a.balance * :rate "
         + "WHERE a.type = 'SAVINGS'")
    int applyInterest(@Param("rate") BigDecimal rate);

    @Modifying(clearAutomatically = true)
    @Query("DELETE FROM Account a WHERE a.balance = 0 AND a.type = 'CURRENT'")
    int purgeEmptyCurrentAccounts();
}
