package com.bank.interest.service;

import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;

@Service
public class InterestService {
    private final AccountRepository repo;
    public InterestService(AccountRepository repo) { this.repo = repo; }

    @Transactional   // modifying query must run in a transaction
    public int applyMonthlyInterest(BigDecimal rate) {
        return repo.applyInterest(rate);
    }
}
